public record GeneratePeriodsResponse(int made) {
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Splits the import into lines (blank lines skipped) and checks each is name,period,amount with an
 * amount of two decimals, 0.00 or more; the first line that fails refuses the whole import. An import
 * with no lines is refused too.
 */
public class ValidateImportOpenings {
    public void validate(@RequestBody ImportOpeningsRequest request, Out<ImportOpeningsLines> linesOut)
            throws InvalidPeriodException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<OpeningLine> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n|\\r")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", -1);
            if (fields.length != 3) throw new InvalidPeriodException("Line " + number + ": name,period,amount");
            String name = fields[0].trim();
            String period = fields[1].trim();
            String amount = fields[2].trim();
            if (name.isEmpty()) throw new InvalidPeriodException("Line " + number + ": a name is required");
            if (period.isEmpty()) throw new InvalidPeriodException("Line " + number + ": a period is required");
            if (!amount.matches("\\d+\\.\\d{2}")) {
                throw new InvalidPeriodException("Line " + number + ": an amount of two decimals, 0.00 or more");
            }
            lines.add(new OpeningLine(name, period, new BigDecimal(amount)));
        }
        if (lines.isEmpty()) throw new InvalidPeriodException("Paste at least one line of name,period,amount");
        linesOut.set(new ImportOpeningsLines(lines));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;

/** The pasted opening balances, each well formed, in the order pasted. */
public record ImportOpeningsLines(List<OpeningLine> lines) {
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Resolves every line first (the person on the sheet by name or alias, the period on the sheet), so
 * one refused line writes nothing; then adds each amount to the person's opening balance for the
 * period, in order, auditing it (OPENING_SET, with the person's own name).
 */
public class SetImportedOpenings {
    public void set(@Val Sheet sheet, @Val ImportOpeningsLines lines, PersonRepository people,
            PeriodRepository periods, HttpServletRequest request, Audit audit, Out<ImportOpeningsResponse> result)
            throws InvalidPeriodException {
        List<Person> persons = new ArrayList<>();
        List<Period> found = new ArrayList<>();
        int number = 0;
        for (OpeningLine line : lines.lines()) {
            number++;
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) {
                throw new InvalidPeriodException("Line " + number + ": no one named " + line.name() + " is on the sheet");
            }
            Period period = periods.find(sheet.id(), line.period());
            if (period == null) {
                throw new InvalidPeriodException("Line " + number + ": no period " + line.period() + " is on the sheet");
            }
            persons.add(person);
            found.add(period);
        }
        String user = Audit.user(request);
        for (int i = 0; i < persons.size(); i++) {
            Person person = persons.get(i);
            Period period = found.get(i);
            OpeningLine line = lines.lines().get(i);
            periods.addOpening(sheet.id(), period.name(), person.getId(), line.amount());
            audit.record("OPENING_SET sheet=" + sheet.id() + " by=" + user + " name=" + person.getName()
                    + " period=" + period.name() + " amount=" + line.amount().setScale(2).toPlainString());
        }
        result.set(new ImportOpeningsResponse(persons.size()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;

/** A pasted opening balance: the person's name (or alias), the period's name and the amount. */
public record OpeningLine(String name, String period, BigDecimal amount) {
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithImportOpenings {
    public void respond(@Val ImportOpeningsResponse result, ObjectResponse<ImportOpeningsResponse> response) {
        response.send(result);
    }
}

